def walk_path(I):
    H,W=len(I),len(I[0])
    nodes={(r,c) for r in range(H) for c in range(W) if I[r][c]==8}
    def deg(p): return sum(1 for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)] if (p[0]+dr,p[1]+dc) in nodes)
    ends=[p for p in nodes if deg(p)==1]
    path=[];prev=None
    for e in ends:
        cur=e
        while True:
            path.append(cur)
            nxt=[q for q in nodes if max(abs(q[0]-cur[0]),abs(q[1]-cur[1]))==1 and q!=prev]
            if not nxt or prev is None and len(nxt)==1: break
            if not nxt: break
            prev=cur; cur=nxt[0]
    # keep only the first valid traversal
    return path
for n_ in (1,2,3):
    I=G[f'Demo pair {n_} input']; O=G[f'Demo pair {n_} output']
    P=walk_path(I)
    print('pair',n_,'path len',len(P),'colors along path:',collections.Counter(O[r][c] for r,c in P))

