                if set(ws)<=rem:
                    cand.append((tuple(sorted(ws)),1))
                elif sum(p in rem for p in ws)==3:
                    absent=[p for p in ws if p not in rem][0]
                    pres=[p for p in ws if p in rem]
                    cy=min(p[0] for p in pres); cx=min(p[1] for p in pres)
                    vert='up' if absent[0]==cy else 'down'; horz='l' if absent[1]==cx else 'r'
                    dv=OPVAL['u'+horz if vert=='up' else 'd'+horz]
                    cand.append((tuple(sorted(pres)),dv))
        if not cand: return None
        ssq=[x for x in cand if x[1]==1]
        s=min(ssq or cand,key=lambda x:x[0][0]*W+x[0][1])
        val=s[1]
        for p in s: out[p]=val
        rem-=set(s)
    return np.array([[out.get((i,j),0) for j in range(W)] for i in range(H)])
for n in [1,2,3]:
    P=solve(G[f'Demo pair {n} input'])
    print(n, P is not None and np.array_equal(P,np.array(G[f'Demo pair {n} output'])))
